<script lang="ts">
  import { pokedex } from '../stores/pokedex.svelte.ts';
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import PokedexCollectionContent from './pokedex/PokedexCollectionContent.svelte';
  import PokedexList from './pokedex/PokedexList.svelte';

  function refreshPokedexDisplay(): void {
    const gm = game as GameRuntime | null;
    if (gm && typeof gm.updatePokedexDisplay === 'function') {
      gm.updatePokedexDisplay();
    }
  }

  function onCollectionGenFilterChange(e: Event): void {
    const gm = game as GameRuntime | null;
    if (!gm) return;
    gm.collectionBonusGenFilter = (e.currentTarget as HTMLSelectElement).value;
    refreshPokedexDisplay();
  }

  function onCollectionOwnershipFilterChange(e: Event): void {
    const gm = game as GameRuntime | null;
    if (!gm) return;
    gm.collectionBonusOwnershipFilter = (e.currentTarget as HTMLSelectElement).value;
    refreshPokedexDisplay();
  }

  let collectionGenFilter = $derived(
    ((game as GameRuntime | null)?.collectionBonusGenFilter) ?? 'all',
  );
  let collectionOwnershipFilter = $derived(
    ((game as GameRuntime | null)?.collectionBonusOwnershipFilter) ?? 'all',
  );

  let snap = $derived(pokedex.snapshot);
  let ui = $derived(snap.ui);
  let isCollection = $derived(snap.activeSubTab === 'collectionbonuses');
  let isPokedex = $derived(!isCollection);

  function sortBtnClass(btn: { key: string; active: boolean; order: 'asc' | 'desc' | null }): string {
    let c = 'sort-btn pokedex-sort-btn';
    if (btn.active) {
      c += ' active';
      if (btn.order) c += ` ${btn.order}`;
    }
    return c;
  }

  function sortLabelId(key: string): string {
    if (key === 'id') return 'pokedexSortNumberLabel';
    if (key === 'name') return 'pokedexSortNameLabel';
    if (key === 'rarity') return 'pokedexSortRarityLabel';
    if (key === 'count') return 'pokedexSortOwnedLabel';
    return 'pokedexSortTypeLabel';
  }

  let collectionGenOptions = $derived([
    { value: '1', label: ui.gen1 },
    { value: '2', label: ui.gen2 },
    { value: '3', label: ui.gen3 },
    { value: '4', label: ui.gen4 },
    { value: '5', label: ui.gen5 },
    { value: '6', label: ui.gen6 },
    { value: '7', label: ui.gen7 },
    { value: '8', label: ui.gen8 },
    { value: '9', label: ui.gen9 },
  ]);
</script>

<!-- Cible = #pokedexTab -->
<div class="sub-tabs-container pokedex-subtab-row" role="tablist" aria-label={ui.subTabsAriaLabel}>
  <button id="pokedexSubTab-pokedex" type="button" class="sub-tab-btn pokedex-subtab-btn" class:active={isPokedex} role="tab"
    aria-selected={isPokedex} aria-controls="pokedexSubView-pokedex" tabindex={isPokedex ? 0 : -1}
    data-action="switchPokedexSubTab" data-arg="pokedex">
    <span id="pokedexSubTabMainLabel">{ui.subMain}</span>
  </button>
  <button id="pokedexSubTab-collectionbonuses" type="button" class="sub-tab-btn pokedex-subtab-btn" class:active={isCollection} role="tab"
    aria-selected={isCollection} aria-controls="pokedexSubView-collectionbonuses" tabindex={isCollection ? 0 : -1}
    data-action="switchPokedexSubTab" data-arg="collectionbonuses">
    <span id="pokedexSubTabBonusLabel">{ui.subBonus}</span>
  </button>
</div>

<div id="pokedexSubView-pokedex" role="tabpanel" aria-labelledby="pokedexSubTab-pokedex"
  class:active={isPokedex} hidden={isCollection} style:display={isPokedex ? '' : 'none'}>
  
  <div class="pokedex-header-block">
    <div class="pokedex-header-row">
      <h3 class="pokedex-section-title">
        <span id="pokedexTitleLabel">{ui.title}</span>
      </h3>
      <div class="pokedex-header-stats">
        <span class="pokedex-count-text">
          <span id="pokedexCount">{snap.pokedexCount}</span> / <span id="pokedexTotal">{snap.pokedexTotal}</span> <span id="pokedexDiscoveredLabel">{ui.discovered}</span>
        </span>
        <span class="pokedex-stats-sep">·</span>
        <span class="pokedex-percent-text">{snap.pokedexPercent} %</span>
        <span class="pokedex-stats-sep">·</span>
        <span class="pokedex-missing-text">{snap.pokedexMissingCount} {ui.missingCountLabel?.replace('{count}', '')?.trim() || 'manquants'}</span>
      </div>
    </div>
    <div class="pokedex-progress-track" title="{snap.pokedexPercent} % complété">
      <div class="pokedex-progress-fill" style="width: {snap.pokedexPercent}%;"></div>
    </div>
  </div>

  <div class="pokedex-controls">
    <div class="pokedex-toolbar-row">
      <div class="pokedex-search-wrap">
        <input
          type="text"
          id="pokedexSearchInput"
          placeholder={ui.searchPlaceholder}
          class="pokedex-search-input"
          oninput={refreshPokedexDisplay}
        />
      </div>
      <div class="pokedex-quick-toggles">
        <button
          type="button"
          class="pokedex-toggle-btn"
          class:active={snap.filterMissingActive}
          data-action="togglePokedexMissingFilter"
          title="Afficher les Pokémon non découverts (silhouettes)"
        >
          {ui.filterMissing}
        </button>
        <button
          type="button"
          class="pokedex-toggle-btn is-shiny"
          class:active={snap.filterShinyActive}
          data-action="togglePokedexShinyFilter"
          title="Afficher uniquement les Pokémon avec une version chromatique découverte"
        >
          {ui.filterShiny}
        </button>
      </div>
    </div>

    <div class="pokedex-gen-chips-row" role="radiogroup" aria-label={ui.genAll}>
      {#each snap.genChips as chip (chip.value)}
        <button
          type="button"
          class="pokedex-gen-chip"
          class:active={chip.active}
          class:is-complete={chip.isComplete}
          data-action="setPokedexGenFilter"
          data-arg={chip.value}
          title={chip.title}
        >
          {chip.label}
        </button>
      {/each}
      <select
        id="pokedexGenFilter"
        class="sr-only"
        value={snap.selectedGen}
        onchange={refreshPokedexDisplay}
        tabindex="-1"
        aria-hidden="true"
      >
        <option value="all">{ui.genAll}</option>
        <option value="1">{ui.gen1}</option>
        <option value="2">{ui.gen2}</option>
        <option value="3">{ui.gen3}</option>
        <option value="4">{ui.gen4}</option>
        <option value="5">{ui.gen5}</option>
        <option value="6">{ui.gen6}</option>
        <option value="7">{ui.gen7}</option>
        <option value="8">{ui.gen8}</option>
        <option value="9">{ui.gen9}</option>
      </select>
    </div>

    <div class="pokedex-sort-row">
      {#each snap.sortButtons as btn (btn.key)}
        <button
          data-action="sortPokedex"
          data-arg={btn.key}
          class={sortBtnClass(btn)}
          id="sort-pokedex-{btn.key}"
        >
          <span id={sortLabelId(btn.key)}>{btn.label}</span>
          {#if btn.active}
            <span class="pokedex-sort-arrow">{btn.order === 'asc' ? '▲' : '▼'}</span>
          {/if}
        </button>
      {/each}
    </div>
  </div>

  <PokedexList />
</div>

<div id="pokedexSubView-collectionbonuses" role="tabpanel" aria-labelledby="pokedexSubTab-collectionbonuses"
  class:active={isCollection} hidden={!isCollection} style:display={isCollection ? '' : 'none'}>
  
  <div class="pokedex-header-block">
    <h3 id="collectionBonusTitleLabel" class="pokedex-section-title">{ui.collectionTitle}</h3>
    <p id="collectionBonusHintLabel" class="pokedex-panel-intro">
      {ui.collectionHint}
    </p>
  </div>

  <div class="pokedex-controls collection-bonus-controls">
    <div class="pokedex-gen-chips-row" role="radiogroup" aria-label={ui.genAll}>
      {#each snap.genChips as chip (chip.value)}
        <button
          type="button"
          class="pokedex-gen-chip"
          class:active={chip.active}
          class:is-complete={chip.isComplete}
          data-action="setPokedexGenFilter"
          data-arg={chip.value}
          title={chip.title}
        >
          {chip.label}
        </button>
      {/each}
      <select
        id="collectionBonusGenFilter"
        class="sr-only"
        value={collectionGenFilter}
        onchange={onCollectionGenFilterChange}
        tabindex="-1"
        aria-hidden="true"
      >
        <option value="all">{ui.genAll}</option>
        {#each collectionGenOptions as gen (gen.value)}
          <option value={gen.value}>{gen.label}</option>
        {/each}
      </select>
    </div>

    <div class="collection-filter-chips-row">
      <button
        type="button"
        class="collection-filter-chip"
        class:active={collectionOwnershipFilter === 'all'}
        data-action="setCollectionOwnershipFilter"
        data-arg="all"
      >
        {ui.collectionFilterAll}
      </button>
      <button
        type="button"
        class="collection-filter-chip"
        class:active={collectionOwnershipFilter === 'almost'}
        data-action="setCollectionOwnershipFilter"
        data-arg="almost"
        title="Collections manquant 2 membres ou moins pour le palier suivant"
      >
        {ui.collectionFilterAlmost}
      </button>
      <button
        type="button"
        class="collection-filter-chip"
        class:active={collectionOwnershipFilter === 'completable'}
        data-action="setCollectionOwnershipFilter"
        data-arg="completable"
        title="Collections dont toutes les espèces sont possédées"
      >
        {ui.collectionFilterCompletable}
      </button>
      <button
        type="button"
        class="collection-filter-chip"
        class:active={collectionOwnershipFilter === 'active'}
        data-action="setCollectionOwnershipFilter"
        data-arg="active"
        title="Collections ayant au moins le Niveau 1 actif"
      >
        {ui.collectionFilterActive}
      </button>

      <select
        id="collectionBonusOwnershipFilter"
        class="sr-only"
        value={collectionOwnershipFilter}
        onchange={onCollectionOwnershipFilterChange}
        tabindex="-1"
        aria-hidden="true"
      >
        <option value="all">{ui.collectionFilterAll}</option>
        <option value="almost">{ui.collectionFilterAlmost}</option>
        <option value="completable">{ui.collectionFilterCompletable}</option>
        <option value="active">{ui.collectionFilterActive}</option>
      </select>
    </div>
  </div>

  <PokedexCollectionContent />
</div>
